#!/usr/bin/env python3
# -*- coding: utf-8 -*-
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def load(p):return json.loads((ROOT/p).read_text())
patch=load('authoring/primary-2026-10/patch.json')
payload={'topics':[t for t in load('data/topics.json') if t['id'].startswith('cnm_p')],'questions':[q for q in load('data/questions.json') if q['topicId'].startswith('cnm_p')],'before':{c['id']:c['before'] for c in patch['questions']},'coverage':load('reviews/math-primary/coverage.json'),'progress':load('reviews/math-primary/progress.json')}
template='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>小学数学 · 首轮审阅</title>
<style>
:root{font-family:system-ui,-apple-system,sans-serif;color:#172b35;background:#f5f7f8;line-height:1.65}body{max-width:1080px;margin:auto;padding:32px 24px}h1{font-size:30px;margin-bottom:8px}h2{font-size:21px}p{margin:8px 0}.muted{color:#536873}.badge{font-size:12px;background:#d9eee6;color:#185843;padding:3px 9px;border-radius:20px;margin-left:12px}.controls{position:sticky;top:0;background:#f5f7f8;padding:16px 0;display:flex;gap:12px;flex-wrap:wrap;z-index:2}input,select{font:inherit;padding:8px;border:1px solid #b4c5cb;border-radius:6px}input{min-width:250px}details.topic{background:white;border:1px solid #d9e2e6;border-radius:10px;margin:12px 0;padding:16px}summary{cursor:pointer;font-weight:600}.question{padding:20px 0;border-top:1px solid #e2e9ec}.question svg{display:block;width:100%;max-width:450px;max-height:310px;margin:15px 0;color:#203d50}.choice svg{width:150px;display:inline-block;vertical-align:middle}.choice{margin:6px 0}.answer{background:#edf5f1;padding:8px 12px}.old{color:#666;border-left:3px solid #c8ced0;padding-left:12px;margin:12px 0}.note{padding:15px;background:#fff4da;border-radius:8px}a{color:#146485}#count{font-weight:600}footer{margin-top:30px;color:#536873}
</style><h1>小学数学 · 首轮审阅</h1><p class="muted">primary-2026-10.1 · 一至六年级 · 216 个知识点 · 864 道题</p>
<p>本轮修订 __CHANGED__ 道题、89 个节点、33 组先修关系。按年级或名称筛选，展开节点可查看题目、答案和原题。</p>
<p class="note">77 条既有课标条目：67 条有部分证据，10 条仍有缺口。这里是可审阅版本，尚未经过教师独立审校或学生试测；实测、作图、调查等能力不能只凭短题判断。</p>
<p><a href="README.md">交付说明</a> · <a href="coverage.json">逐条课标证据</a> · <a href="source-review.json">来源核查与遗漏活动</a> · <a href="../../diagnose/">进入诊断</a></p>
<div class="controls"><label>年级 <select id="grade"><option value="">全部</option><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option><option>6</option></select></label><label>搜索 <input id="query" placeholder="如：折线、余数、cnm_p002"></label></div><p id="count"></p><main id="topics"></main><footer>年级、学期沿用教材型组织；国家课标按学段表述。所有“首轮审阅”记录均不等于专家认证。</footer>
<script>const DATA=__DATA__;
const el=(tag,text,cls)=>{const x=document.createElement(tag);if(text!==undefined)x.textContent=text;if(cls)x.className=cls;return x;};
function figure(svg,host){if(svg){const d=el('div');d.innerHTML=svg;host.append(d);}}
function render(){const grade=document.getElementById('grade').value,term=document.getElementById('query').value.trim().toLowerCase();const selected=DATA.topics.filter(t=>(!grade||String(t.grade)===grade)&&(!term||(t.id+' '+t.name).toLowerCase().includes(term)));document.getElementById('count').textContent='显示 '+selected.length+' / 216 个知识点';const root=document.getElementById('topics');root.replaceChildren();selected.forEach(t=>{const box=el('details',undefined,'topic');box.id=t.id;box.append(el('summary',t.id+' · '+t.grade+' 年级 · '+t.name));const qs=DATA.questions.filter(q=>q.topicId===t.id);box.append(el('p',t.mastery_criteria.join('；'),'muted'));if(t.scope_note)box.append(el('p',t.scope_note,'note'));qs.forEach(q=>{const card=el('section',undefined,'question');card.append(el('p',q.id+' · '+q.difficulty,'muted'));card.append(el('p',q.prompt));figure(q.figure,card);(q.choices||[]).forEach(c=>{const row=el('div',c.key+' '+(q.hideChoiceText?'':c.text),'choice');figure(c.figure,row);card.append(row);});const ans=el('details');ans.append(el('summary','查看答案与解析'));ans.append(el('p','答案：'+q.answer+'。'+q.explanation,'answer'));card.append(ans);if(DATA.before[q.id]){const old=el('details',undefined,'old');old.append(el('summary','查看修订前题目'));old.append(el('p',DATA.before[q.id].prompt));old.append(el('p','原答案：'+DATA.before[q.id].answer));card.append(old);}box.append(card);});root.append(box);});}
document.getElementById('grade').addEventListener('change',render);document.getElementById('query').addEventListener('input',render);render();</script></html>'''
(ROOT/'reviews/math-primary/index.html').write_text(template.replace('__CHANGED__',str(payload['progress']['changedQuestions'])).replace('__DATA__',json.dumps(payload,ensure_ascii=False).replace('<','\\u003c')))
